face.layout_source:
// frequency-shifter.face: the panel for tap/examples/spectral/frequency-shifter.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/frequency-shifter.face --meta <graph>.cragmeta

face "Frequency Shifter" {
  row(gap = 10) {
    box "Shift" { knob.big "Shift" (shift) knob "Mix" (mix) }
    viz(grow = 1)
  }
}
